// Message parsing function for Option B (Structured Format)
// Format:
// URL: https://example.com/article
// Feed: technology
// Note: Optional description

const messageText = msg.payload.content || msg.payload.message.text;
const chatId = msg.payload.chatId || msg.payload.message.chat.id;
const messageId = msg.payload.messageId || msg.payload.message.message_id;
const username = msg.payload.from?.username || msg.payload.message?.from?.username;

// Store chat info for later
msg.chatId = chatId;
msg.messageId = messageId;
msg.username = username;

// If it's a command, ignore it
if (msg.payload.content && msg.payload.content.startsWith('/')) {
  msg.payload = {
    isCommand: true,
    command: msg.payload.content.split(' ')[0]
  };
  return [null, msg];
}

const lines = (messageText || '').split('\n');

// Initialize variables
let url = null;
let feedProfile = null;
let note = null;
const errors = [];

// Parse each line for key-value pairs
lines.forEach(line => {
  const trimmedLine = line.trim();

  // Match URL: label (case-insensitive)
  const urlMatch = trimmedLine.match(/^URL:\s*(.+)$/i);
  if (urlMatch) {
    url = urlMatch[1].trim();
  }

  // Match Feed: label (case-insensitive)
  const feedMatch = trimmedLine.match(/^Feed:\s*(.+)$/i);
  if (feedMatch) {
    feedProfile = feedMatch[1].trim().toLowerCase();
  }

  // Match Note: label (optional, case-insensitive)
  const noteMatch = trimmedLine.match(/^Note:\s*(.+)$/i);
  if (noteMatch) {
    note = noteMatch[1].trim();
  }
});

// Validation
if (!url) {
  errors.push("❌ URL is required. Please include a URL: line.");
}

if (!feedProfile) {
  errors.push("❌ Feed profile is required. Please include a Feed: line.");
}

// URL format validation
if (url && !url.match(/^https?:\/\/.+/i)) {
  errors.push("❌ The URL doesn't appear to be valid. Please check and try again.");
}

// Feed profile validation
const validFeeds = ['default', 'technology', 'politics', 'business', 'health', 'science', 'brasil', 'teclas'];
if (feedProfile && !validFeeds.includes(feedProfile)) {
  errors.push(`❌ Feed '${feedProfile}' doesn't exist. Available feeds: ${validFeeds.join(', ')}`);
}

// Set payload for next node
if (errors.length > 0) {
  msg.payload = {
    url: url,
    feedProfile: feedProfile,
    note: note,
    errors: errors,
    isValid: false
  };
  return [null, msg];
}

msg.payload = {
  url: url,
  feedProfile: feedProfile,
  note: note,
  errors: null,
  isValid: true,
  metadata: {
    chatId: chatId.toString(),
    messageId: messageId.toString(),
    username: username || undefined
  }
};

return [msg, null];

// Format validation errors for Telegram
const errors = msg.payload.errors || [];
let errorMessage = "❌ Submission failed:\n\n";

errors.forEach(err => {
  errorMessage += err + "\n";
});

errorMessage += "\n📝 Use this format:\nURL: https://example.com\nFeed: technology";

msg.payload = {
  chatId: msg.chatId,
  type: "message",
  content: errorMessage
};

return msg;

// Prepare the API request payload
const payload = msg.payload;

msg.url = env.get('MERIDIANO_API_URL') || 'http://100.127.158.111:3001/api/articles/external';
msg.headers = {
  'Content-Type': 'application/json',
  'X-External-Token': flow.get('EXTERNAL_API_TOKEN') || env.get('EXTERNAL_API_TOKEN')
};

msg.payload = {
  url: payload.url,
  feedProfile: payload.feedProfile,
  source: 'telegram',
  metadata: payload.metadata
};

if (payload.note) {
  msg.payload.metadata.note = payload.note;
}

return msg;

// Format success message for Telegram
const response = msg.payload;

let successMessage = "✅ Article submitted successfully!\n\n";

if (response.message) {
  successMessage += response.message + "\n\n";
}

if (response.jobId) {
  successMessage += `🆔 Job ID: \`${response.jobId}\`\n`;
}

if (response.articleId) {
  successMessage += `📄 Article ID: \`${response.articleId}\`\n`;
}

successMessage += "\n⏳ Your article is being processed and will be available soon.";

msg.payload = {
  chatId: msg.chatId,
  type: "message",
  content: successMessage
};

return msg;

// Format error message for Telegram based on error code
const response = msg.payload;
const statusCode = msg.statusCode;

// Error message formatting based on error codes
const errorMessages = {
  INVALID_URL: "❌ The URL you provided doesn't seem valid. Please check and try again.",
  INVALID_FEED_PROFILE: "❌ Invalid feed profile. Use one of: default, technology, politics, business, health, science, brasil, teclas",
  UNAUTHORIZED: "⚠️ Authentication error. Please contact support.",
  RATE_LIMIT_EXCEEDED: "⏳ You're submitting too fast. Please wait a minute before trying again.",
  ARTICLE_EXISTS: "ℹ️ This article has already been submitted before.",
  SCRAPE_FAILED: "❌ Couldn't access the article. Is the URL correct and accessible?",
  INTERNAL_ERROR: "🔥 Something went wrong on our end. Please try again later."
};

// Try to extract error code from response
let errorCode = 'INTERNAL_ERROR';
let errorMessage = 'An error occurred. Please try again later.';

if (response && response.error && response.error.code) {
  errorCode = response.error.code;
  errorMessage = errorMessages[errorCode] || response.error.message || errorMessages.INTERNAL_ERROR;
} else if (statusCode === 401) {
  errorCode = 'UNAUTHORIZED';
  errorMessage = errorMessages.UNAUTHORIZED;
} else if (statusCode === 429) {
  errorCode = 'RATE_LIMIT_EXCEEDED';
  errorMessage = errorMessages.RATE_LIMIT_EXCEEDED;
} else if (statusCode === 409) {
  errorCode = 'ARTICLE_EXISTS';
  errorMessage = errorMessages.ARTICLE_EXISTS;
} else if (statusCode === 502 || statusCode === 503) {
  errorCode = 'SCRAPE_FAILED';
  errorMessage = errorMessages.SCRAPE_FAILED;
}

msg.payload = {
  chatId: msg.chatId,
  type: "message",
  content: errorMessage
};

return msg;

// Handle /start command
const startMessage = `👋 *Welcome to Meridiano Article Bot!*\n\n` +
  `I can help you submit articles for processing.\n\n` +
  `*How to use:*\n` +
  `1. Send me a URL with a feed profile\n` +
  `2. I'll submit it for processing\n` +
  `3. You'll get notified when it's ready\n\n` +
  `Type /help for more information.`;

msg.payload = {
  chatId: msg.chatId,
  type: "message",
  content: startMessage
};

return msg;
